#include <gst/gst.h>
#include <cstring>
#include <iostream>
int main(int argc, char** argv) {
  gst_init(&argc, &argv);
  if (argc != 2) return 2;
  const bool ready = std::strcmp(argv[1], "--ready") == 0;
  const char* name = ready ? "webrtcbin" : argv[1];
  GstElement* element = gst_element_factory_make(name, nullptr);
  if (!element) return 3;
  bool ok = true;
  if (ready) {
    const auto changed = gst_element_set_state(element, GST_STATE_READY);
    GstState current = GST_STATE_NULL;
    const auto waited = gst_element_get_state(element, &current, nullptr, 5 * GST_SECOND);
    ok = changed != GST_STATE_CHANGE_FAILURE && waited != GST_STATE_CHANGE_FAILURE && current == GST_STATE_READY;
    gst_element_set_state(element, GST_STATE_NULL);
  }
  gst_object_unref(element);
  std::cout << "{\"factory\":\"" << name << "\",\"created\":true,\"ready\":" << (ready && ok ? "true" : "false") << "}\n";
  gst_deinit();
  return ok ? 0 : 4;
}

